//! Scriptable HTTP/1.1 file server for the hidden tests and the benchmark.
//! One thread per connection, `Connection: close` on every response.

use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::atomic::{AtomicU64, AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Duration;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum RangeMode {
    /// 206 + `Content-Range: bytes a-b/total` for any Range request.
    Full,
    /// Ignores Range, always 200 with the whole body.
    Ignore,
    /// Range requests get 206 with an unknown total (`bytes a-b/*`); plain GET gets 200.
    UnknownTotal,
}

#[derive(Clone, Debug)]
pub struct Behavior {
    pub range: RangeMode,
    /// Respond with this status (and empty body) to every request.
    pub status: Option<u16>,
    /// The first `drop_count` non-probe body responses send only `drop_after` bytes, then close.
    pub drop_after: usize,
    pub drop_count: usize,
    /// Non-probe range responses claim a start one byte later than requested.
    pub wrong_range: bool,
    /// Non-probe range responses carry one extra byte.
    pub oversize: bool,
    /// Per-connection bandwidth in bytes/s (None = unthrottled).
    pub throttle_bps: Option<u64>,
    /// Every `slow_every`-th connection (1-based) is throttled to `slow_bps` instead.
    pub slow_every: usize,
    pub slow_bps: u64,
    /// Path that redirects (302) to the file path.
    pub redirect: bool,
}

impl Default for Behavior {
    fn default() -> Self {
        Behavior {
            range: RangeMode::Full,
            status: None,
            drop_after: 0,
            drop_count: 0,
            wrong_range: false,
            oversize: false,
            throttle_bps: None,
            slow_every: 0,
            slow_bps: 0,
            redirect: false,
        }
    }
}

#[derive(Clone, Debug)]
pub struct Logged {
    pub path: String,
    pub headers: Vec<(String, String)>, // lower-case names
    pub range: Option<(u64, Option<u64>)>,
}

impl Logged {
    pub fn header(&self, name: &str) -> Option<&str> {
        self.headers.iter().find(|(k, _)| k == name).map(|(_, v)| v.as_str())
    }
}

pub struct Server {
    pub url: String,
    pub redirect_url: String,
    pub log: Arc<Mutex<Vec<Logged>>>,
    pub active: Arc<AtomicUsize>,
    pub max_active: Arc<AtomicUsize>,
    pub served_bytes: Arc<AtomicU64>,
}

impl Server {
    pub fn requests(&self) -> Vec<Logged> {
        self.log.lock().unwrap().clone()
    }
}

pub fn start(data: Arc<Vec<u8>>, behavior: Behavior) -> Server {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let addr = listener.local_addr().unwrap();
    let log = Arc::new(Mutex::new(Vec::new()));
    let active = Arc::new(AtomicUsize::new(0));
    let max_active = Arc::new(AtomicUsize::new(0));
    let served = Arc::new(AtomicU64::new(0));
    let drops_left = Arc::new(AtomicUsize::new(behavior.drop_count));
    let conn_no = Arc::new(AtomicUsize::new(0));
    {
        let (log, active, max_active, served) =
            (log.clone(), active.clone(), max_active.clone(), served.clone());
        std::thread::spawn(move || {
            for stream in listener.incoming() {
                let Ok(stream) = stream else { continue };
                let n = conn_no.fetch_add(1, Ordering::SeqCst) + 1;
                let ctx = Ctx {
                    data: data.clone(),
                    b: behavior.clone(),
                    log: log.clone(),
                    active: active.clone(),
                    max_active: max_active.clone(),
                    served: served.clone(),
                    drops_left: drops_left.clone(),
                    conn_no: n,
                };
                std::thread::spawn(move || {
                    let _ = handle(stream, ctx);
                });
            }
        });
    }
    Server {
        url: format!("http://{addr}/file.bin"),
        redirect_url: format!("http://{addr}/redirect"),
        log,
        active,
        max_active,
        served_bytes: served,
    }
}

struct Ctx {
    data: Arc<Vec<u8>>,
    b: Behavior,
    log: Arc<Mutex<Vec<Logged>>>,
    active: Arc<AtomicUsize>,
    max_active: Arc<AtomicUsize>,
    served: Arc<AtomicU64>,
    drops_left: Arc<AtomicUsize>,
    conn_no: usize,
}

fn read_head(stream: &mut TcpStream) -> Option<String> {
    let mut buf = Vec::new();
    let mut byte = [0u8; 1024];
    while !buf.windows(4).any(|w| w == b"\r\n\r\n") {
        let n = stream.read(&mut byte).ok()?;
        if n == 0 {
            return None;
        }
        buf.extend_from_slice(&byte[..n]);
        if buf.len() > 64 * 1024 {
            return None;
        }
    }
    Some(String::from_utf8_lossy(&buf).into_owned())
}

fn parse_range(v: &str) -> Option<(u64, Option<u64>)> {
    let v = v.trim().strip_prefix("bytes=")?;
    let (a, b) = v.split_once('-')?;
    let a = a.trim().parse().ok()?;
    let b = b.trim();
    Some((a, if b.is_empty() { None } else { Some(b.parse().ok()?) }))
}

fn handle(mut stream: TcpStream, c: Ctx) -> std::io::Result<()> {
    let Some(head) = read_head(&mut stream) else { return Ok(()) };
    let mut lines = head.split("\r\n");
    let request_line = lines.next().unwrap_or("");
    let path = request_line.split_whitespace().nth(1).unwrap_or("/").to_string();
    let headers: Vec<(String, String)> = lines
        .filter_map(|l| l.split_once(':'))
        .map(|(k, v)| (k.trim().to_ascii_lowercase(), v.trim().to_string()))
        .collect();
    let range = headers.iter().find(|(k, _)| k == "range").and_then(|(_, v)| parse_range(v));
    c.log.lock().unwrap().push(Logged { path: path.clone(), headers, range });

    let now = c.active.fetch_add(1, Ordering::SeqCst) + 1;
    c.max_active.fetch_max(now, Ordering::SeqCst);
    let result = respond(&mut stream, &c, &path, range);
    c.active.fetch_sub(1, Ordering::SeqCst);
    result
}

fn respond(
    stream: &mut TcpStream,
    c: &Ctx,
    path: &str,
    range: Option<(u64, Option<u64>)>,
) -> std::io::Result<()> {
    if c.b.redirect && path == "/redirect" {
        return write!(
            stream,
            "HTTP/1.1 302 Found\r\nLocation: /file.bin\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
        );
    }
    if let Some(code) = c.b.status {
        return write!(
            stream,
            "HTTP/1.1 {code} Status\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
        );
    }
    let total = c.data.len() as u64;
    let probe = range == Some((0, Some(0)));
    let (status, start, end, content_range) = match (c.b.range, range) {
        (RangeMode::Full, Some((a, b))) | (RangeMode::UnknownTotal, Some((a, b))) if a < total => {
            let e = b.unwrap_or(total - 1).min(total - 1);
            let shown = if c.b.wrong_range && !probe { a + 1 } else { a };
            let t = if c.b.range == RangeMode::Full { total.to_string() } else { "*".into() };
            ("206 Partial Content", a, e, Some(format!("bytes {shown}-{e}/{t}")))
        }
        _ if total == 0 => ("200 OK", 0, 0, None),
        _ => ("200 OK", 0, total - 1, None),
    };
    let mut body: Vec<u8> = if total == 0 { Vec::new() } else { c.data[start as usize..=end as usize].to_vec() };
    if c.b.oversize && content_range.is_some() && !probe {
        body.push(0xAB);
    }
    let mut head = format!("HTTP/1.1 {status}\r\nContent-Length: {}\r\n", body.len());
    if let Some(cr) = content_range {
        head.push_str(&format!("Content-Range: {cr}\r\n"));
    }
    head.push_str("Accept-Ranges: bytes\r\nConnection: close\r\n\r\n");
    stream.write_all(head.as_bytes())?;

    let mut limit = body.len();
    if !probe && c.b.drop_count > 0 {
        let took = c
            .drops_left
            .fetch_update(Ordering::SeqCst, Ordering::SeqCst, |n| n.checked_sub(1))
            .is_ok();
        if took {
            limit = c.b.drop_after.min(body.len());
        }
    }
    let bps = if c.b.slow_every > 0 && c.conn_no % c.b.slow_every == 0 {
        Some(c.b.slow_bps)
    } else {
        c.b.throttle_bps
    };
    const CHUNK: usize = 64 * 1024;
    let mut sent = 0;
    while sent < limit {
        let n = CHUNK.min(limit - sent);
        stream.write_all(&body[sent..sent + n])?;
        c.served.fetch_add(n as u64, Ordering::SeqCst);
        sent += n;
        // no sleep after the last chunk: the client already has every byte, and a lingering
        // handler would be counted as a concurrent connection.
        if let Some(bps) = bps.filter(|_| sent < limit) {
            std::thread::sleep(Duration::from_secs_f64(n as f64 / bps as f64));
        }
    }
    if limit < body.len() {
        let _ = stream.shutdown(std::net::Shutdown::Both);
    }
    Ok(())
}
//! P1 benchmark: median wall time of 3 runs per scenario (release build).
use seg_harness::segmented_download::{download, DownloadRequest};
use seg_harness::server::{self, Behavior};
use std::sync::atomic::AtomicBool;
use std::sync::Arc;
use std::time::Instant;

fn once(body: &Arc<Vec<u8>>, b: &Behavior) -> f64 {
    let s = server::start(body.clone(), b.clone());
    let dir = std::env::temp_dir().join(format!("seg-bench-{}-{}", std::process::id(),
        std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));
    std::fs::create_dir_all(&dir).unwrap();
    let dest = dir.join("f.bin");
    let rt = tokio::runtime::Builder::new_multi_thread().worker_threads(4).enable_all().build().unwrap();
    let t = Instant::now();
    let out = rt.block_on(download(
        DownloadRequest { url: s.url.clone(), destination: dest.clone(), cookie_header: None, referer: None },
        Arc::new(AtomicBool::new(false)),
        |_| {},
    ));
    let secs = t.elapsed().as_secs_f64();
    assert!(matches!(out, Ok(Some(_))), "bench download failed: {out:?}");
    assert_eq!(std::fs::metadata(&dest).unwrap().len(), body.len() as u64);
    std::fs::remove_dir_all(dir).ok();
    secs
}

fn median(body: &Arc<Vec<u8>>, b: &Behavior) -> f64 {
    let mut v: Vec<f64> = (0..3).map(|_| once(body, b)).collect();
    v.sort_by(|a, b| a.partial_cmp(b).unwrap());
    v[1]
}

fn main() {
    const MB: usize = 1_000_000;
    let body80 = Arc::new((0..80 * MB).map(|i| (i % 251) as u8).collect::<Vec<u8>>());
    let body512 = Arc::new((0..512 * MB).map(|i| (i % 251) as u8).collect::<Vec<u8>>());
    let throttled = Behavior { throttle_bps: Some(10 * MB as u64), ..Default::default() };
    let uneven = Behavior { throttle_bps: Some(10 * MB as u64), slow_every: 3, slow_bps: MB as u64, ..Default::default() };
    println!(
        "perf  throttled 80MB@10MB/s/conn {:.2}s | uneven 80MB (every 3rd conn 1MB/s) {:.2}s | unthrottled 512MB {:.2}s",
        median(&body80, &throttled),
        median(&body80, &uneven),
        median(&body512, &Behavior::default()),
    );
}

//! HTTP Range 기반 분할 다운로드 백엔드.
//!
//! 배포 사이트 자동화는 `dist_host.rs`가 담당하고, 이 모듈은 최종 파일 URL을 받은 뒤의
//! 전송·재시도·재개만 담당한다. 서버가 Range를 지원하지 않으면 단일 스트림으로 폴백한다.

use reqwest::header::{ACCEPT_ENCODING, CONTENT_LENGTH, CONTENT_RANGE, COOKIE, RANGE, REFERER};
use reqwest::{Client, StatusCode};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, AtomicU64, AtomicUsize, Ordering};
use std::sync::{Arc, LazyLock};
use std::time::{Duration, Instant};
use tokio::io::{AsyncSeekExt, AsyncWriteExt};
use tokio::sync::Mutex;
use tokio::task::JoinSet;

/// 취소는 협조적이다: 실행 중인 전송이 이 sentinel을 Err로 올리면 `download`가
/// 실패가 아니라 취소(`Ok(None)`)로 변환한다. sidecar는 남겨 재개할 수 있게 한다.
const CANCEL_SENTINEL: &str = "__DIST_DOWNLOAD_CANCELLED__";

/// 진행 중인 다운로드의 취소 플래그 레지스트리(토큰 → 플래그).
/// 다운로드 task는 `dist_host`가 spawn하므로, 취소 커맨드가 토큰으로 찾아 신호할 수 있게
/// 한 곳에 모은다.
static CANCELLERS: LazyLock<std::sync::Mutex<HashMap<String, Arc<AtomicBool>>>> =
    LazyLock::new(|| std::sync::Mutex::new(HashMap::new()));

/// 토큰에 대한 취소 플래그를 만들어 등록하고 돌려준다.
pub fn register_cancel(token: &str) -> Arc<AtomicBool> {
    let flag = Arc::new(AtomicBool::new(false));
    if let Ok(mut map) = CANCELLERS.lock() {
        map.insert(token.to_string(), flag.clone());
    }
    flag
}

/// 해당 토큰의 다운로드에 취소를 신호한다. 등록된 게 있으면 true.
pub fn request_cancel(token: &str) -> bool {
    if let Ok(map) = CANCELLERS.lock() {
        if let Some(flag) = map.get(token) {
            flag.store(true, Ordering::SeqCst);
            return true;
        }
    }
    false
}

/// 완료·실패·취소로 끝난 토큰의 플래그를 제거한다.
pub fn clear_cancel(token: &str) {
    if let Ok(mut map) = CANCELLERS.lock() {
        map.remove(token);
    }
}

fn cancelled(flag: &AtomicBool) -> bool {
    flag.load(Ordering::Relaxed)
}

const CONNECTIONS: usize = 8;
const SEGMENTS_PER_CONNECTION: usize = 2;
const MAX_RETRIES: usize = 4;
const PROGRESS_EMIT_INTERVAL: Duration = Duration::from_millis(250);
const RESUME_CHECKPOINT_BYTES: u64 = 1024 * 1024;
const USER_AGENT: &str = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 \
     (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36";

#[derive(Debug, Clone)]
pub struct DownloadRequest {
    pub url: String,
    pub destination: PathBuf,
    pub cookie_header: Option<String>,
    pub referer: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum DownloadMode {
    Segmented,
    Single,
}

#[derive(Debug, Clone, Copy)]
pub struct DownloadProgress {
    pub received: u64,
    pub total: Option<u64>,
    pub mode: DownloadMode,
}

#[derive(Debug, Serialize, Deserialize)]
struct ResumeMeta {
    version: u8,
    total: u64,
    segment_count: usize,
}

struct ProgressEmitter {
    received: Arc<AtomicU64>,
    total: Option<u64>,
    mode: DownloadMode,
    last_emit_ms: AtomicU64,
    started: Instant,
    callback: Arc<dyn Fn(DownloadProgress) + Send + Sync>,
}

impl ProgressEmitter {
    fn new(
        received: Arc<AtomicU64>,
        total: Option<u64>,
        mode: DownloadMode,
        callback: Arc<dyn Fn(DownloadProgress) + Send + Sync>,
    ) -> Self {
        Self {
            received,
            total,
            mode,
            last_emit_ms: AtomicU64::new(0),
            started: Instant::now(),
            callback,
        }
    }

    fn emit_if_due(&self) {
        let elapsed = self.started.elapsed().as_millis().min(u64::MAX as u128) as u64;
        let last = self.last_emit_ms.load(Ordering::Relaxed);
        if elapsed.saturating_sub(last) < PROGRESS_EMIT_INTERVAL.as_millis() as u64 {
            return;
        }
        if self
            .last_emit_ms
            .compare_exchange(last, elapsed, Ordering::Relaxed, Ordering::Relaxed)
            .is_ok()
        {
            self.emit();
        }
    }

    fn emit(&self) {
        (self.callback)(DownloadProgress {
            received: self.received.load(Ordering::Relaxed),
            total: self.total,
            mode: self.mode,
        });
    }
}

fn client() -> Result<Client, String> {
    Client::builder()
        .connect_timeout(Duration::from_secs(20))
        .redirect(reqwest::redirect::Policy::limited(10))
        .user_agent(USER_AGENT)
        .build()
        .map_err(|e| format!("HTTP 클라이언트 생성 실패: {e}"))
}

fn request(
    client: &Client,
    method: reqwest::Method,
    request: &DownloadRequest,
) -> reqwest::RequestBuilder {
    let mut builder = client
        .request(method, &request.url)
        // 압축된 응답은 바이트 오프셋과 실제 파일 오프셋을 다르게 만들 수 있다.
        .header(ACCEPT_ENCODING, "identity");
    if let Some(cookie) = request.cookie_header.as_deref().filter(|v| !v.is_empty()) {
        builder = builder.header(COOKIE, cookie);
    }
    if let Some(referer) = request.referer.as_deref().filter(|v| !v.is_empty()) {
        builder = builder.header(REFERER, referer);
    }
    builder
}

fn parse_content_range(value: &str) -> Option<u64> {
    // `bytes 0-0/4722087959`; 크기를 모르는 `bytes 0-0/*`는 거부한다.
    let (_, total) = value.rsplit_once('/')?;
    total.parse::<u64>().ok().filter(|n| *n > 0)
}

async fn probe_range(
    client: &Client,
    request_info: &DownloadRequest,
) -> Result<(bool, Option<u64>), String> {
    let response = request(client, reqwest::Method::GET, request_info)
        .header(RANGE, "bytes=0-0")
        .send()
        .await
        .map_err(|e| format!("다운로드 서버 연결 실패: {e}"))?;

    if response.status() == StatusCode::PARTIAL_CONTENT {
        let total = response
            .headers()
            .get(CONTENT_RANGE)
            .and_then(|v| v.to_str().ok())
            .and_then(parse_content_range);
        return Ok((total.is_some(), total));
    }

    if response.status().is_success() {
        let total = response
            .headers()
            .get(CONTENT_LENGTH)
            .and_then(|v| v.to_str().ok())
            .and_then(|v| v.parse::<u64>().ok())
            .filter(|n| *n > 0);
        return Ok((false, total));
    }

    Err(format!(
        "다운로드 서버가 요청을 거부했습니다: HTTP {}",
        response.status()
    ))
}

fn sidecar_path(destination: &Path, suffix: &str) -> PathBuf {
    let name = destination
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| "download".to_string());
    destination.with_file_name(format!("{name}.{suffix}"))
}

/// 저장된 구간 오프셋을 검증한다. 정상 checkpoint는 `completed`(≤ 구간 길이)만 기록하므로
/// 구간 길이를 넘는 값은 손상(예: 하드 크래시 중 상태 파일 torn-write)이다.
/// 그런 값을 완료로 오인하면 미수신 바이트를 건너뛰어 파일이 조용히 손상되므로,
/// 처음부터 다시 받도록 0으로 되돌린다.
fn valid_resume_offset(saved: u64, segment_len: u64) -> u64 {
    if saved <= segment_len {
        saved
    } else {
        0
    }
}

fn segment_bounds(total: u64, count: usize, index: usize) -> (u64, u64) {
    let count = count.max(1) as u64;
    let index = index as u64;
    let base = total / count;
    let remainder = total % count;
    // 나머지 바이트를 앞쪽 구간에 하나씩 배분하면 모든 구간이 빈틈·중복 없이 이어진다.
    let start = index * base + index.min(remainder);
    let size = base + u64::from(index < remainder);
    let end = start.saturating_add(size).saturating_sub(1);
    (start, end)
}

async fn prepare_resume(
    destination: &Path,
    total: u64,
    segment_count: usize,
) -> Result<(PathBuf, PathBuf, PathBuf, Vec<u64>), String> {
    let part_path = sidecar_path(destination, "download");
    let meta_path = sidecar_path(destination, "download.json");
    let state_path = sidecar_path(destination, "download.state");
    let expected = ResumeMeta {
        version: 1,
        total,
        segment_count,
    };

    let existing_meta = tokio::fs::read_to_string(&meta_path)
        .await
        .ok()
        .and_then(|s| serde_json::from_str::<ResumeMeta>(&s).ok());
    let reusable = existing_meta
        .as_ref()
        .is_some_and(|m| m.version == 1 && m.total == total && m.segment_count == segment_count)
        && tokio::fs::metadata(&part_path)
            .await
            .is_ok_and(|m| m.len() == total);

    if !reusable {
        for path in [&part_path, &meta_path, &state_path] {
            if let Err(e) = tokio::fs::remove_file(path).await {
                if e.kind() != std::io::ErrorKind::NotFound {
                    return Err(format!("이전 임시 파일 정리 실패({}): {e}", path.display()));
                }
            }
        }
        let file = tokio::fs::File::create(&part_path)
            .await
            .map_err(|e| format!("임시 파일 생성 실패({}): {e}", part_path.display()))?;
        file.set_len(total)
            .await
            .map_err(|e| format!("임시 파일 크기 설정 실패: {e}"))?;
        tokio::fs::write(
            &meta_path,
            serde_json::to_vec(&expected).map_err(|e| format!("재개 정보 생성 실패: {e}"))?,
        )
        .await
        .map_err(|e| format!("재개 정보 저장 실패: {e}"))?;
        tokio::fs::write(&state_path, vec![0u8; segment_count * 8])
            .await
            .map_err(|e| format!("구간 상태 생성 실패: {e}"))?;
    }

    let raw_state = tokio::fs::read(&state_path).await.unwrap_or_default();
    let mut offsets = Vec::with_capacity(segment_count);
    for index in 0..segment_count {
        let pos = index * 8;
        let value = raw_state
            .get(pos..pos + 8)
            .and_then(|bytes| bytes.try_into().ok())
            .map(u64::from_le_bytes)
            .unwrap_or(0);
        let (start, end) = segment_bounds(total, segment_count, index);
        let segment_len = end.saturating_sub(start).saturating_add(1);
        offsets.push(valid_resume_offset(value, segment_len));
    }
    Ok((part_path, meta_path, state_path, offsets))
}

async fn download_segment(
    client: &Client,
    request_info: &DownloadRequest,
    part_path: &Path,
    state_file: Arc<Mutex<tokio::fs::File>>,
    progress: Arc<ProgressEmitter>,
    cancel: Arc<AtomicBool>,
    segment_count: usize,
    index: usize,
    initial_offset: u64,
) -> Result<(), String> {
    let total = progress
        .total
        .expect("분할 다운로드는 전체 크기가 필요하다");
    let (segment_start, segment_end) = segment_bounds(total, segment_count, index);
    let segment_len = segment_end.saturating_sub(segment_start).saturating_add(1);
    if initial_offset >= segment_len {
        return Ok(());
    }

    let mut completed = initial_offset;
    let mut checkpointed = initial_offset;
    for attempt in 0..MAX_RETRIES {
        if cancelled(&cancel) {
            return Err(CANCEL_SENTINEL.to_string());
        }
        let start = segment_start + completed;
        let mut response = match request(client, reqwest::Method::GET, request_info)
            .header(RANGE, format!("bytes={start}-{segment_end}"))
            .send()
            .await
        {
            Ok(response) if response.status() == StatusCode::PARTIAL_CONTENT => response,
            Ok(response) => {
                return Err(format!(
                    "Range 응답이 아닙니다(구간 {index}, HTTP {})",
                    response.status()
                ))
            }
            Err(e) if attempt + 1 < MAX_RETRIES => {
                tokio::time::sleep(Duration::from_millis(500 * (attempt as u64 + 1))).await;
                eprintln!("[segmented-download] 구간 {index} 재시도: {e}");
                continue;
            }
            Err(e) => return Err(format!("구간 {index} 다운로드 실패: {e}")),
        };
        let expected_range_prefix = format!("bytes {start}-");
        let valid_range = response
            .headers()
            .get(CONTENT_RANGE)
            .and_then(|value| value.to_str().ok())
            .is_some_and(|value| value.starts_with(&expected_range_prefix));
        if !valid_range {
            return Err(format!(
                "구간 {index}의 Content-Range가 요청 범위와 다릅니다"
            ));
        }

        let mut file = tokio::fs::OpenOptions::new()
            .write(true)
            .open(part_path)
            .await
            .map_err(|e| format!("임시 파일 열기 실패: {e}"))?;
        file.seek(std::io::SeekFrom::Start(start))
            .await
            .map_err(|e| format!("구간 {index} seek 실패: {e}"))?;

        let transfer = async {
            while let Some(chunk) = response
                .chunk()
                .await
                .map_err(|e| format!("구간 {index} 수신 실패: {e}"))?
            {
                if cancelled(&cancel) {
                    return Err(CANCEL_SENTINEL.to_string());
                }
                let remaining = segment_len.saturating_sub(completed);
                if chunk.len() as u64 > remaining {
                    return Err(format!("구간 {index}이 예정 크기를 초과했습니다"));
                }
                file.write_all(&chunk)
                    .await
                    .map_err(|e| format!("구간 {index} 쓰기 실패: {e}"))?;
                completed += chunk.len() as u64;
                progress
                    .received
                    .fetch_add(chunk.len() as u64, Ordering::Relaxed);
                progress.emit_if_due();

                if completed.saturating_sub(checkpointed) >= RESUME_CHECKPOINT_BYTES
                    || completed == segment_len
                {
                    let mut state = state_file.lock().await;
                    state
                        .seek(std::io::SeekFrom::Start((index * 8) as u64))
                        .await
                        .map_err(|e| format!("구간 상태 seek 실패: {e}"))?;
                    state
                        .write_all(&completed.to_le_bytes())
                        .await
                        .map_err(|e| format!("구간 상태 저장 실패: {e}"))?;
                    checkpointed = completed;
                }
            }
            file.flush()
                .await
                .map_err(|e| format!("구간 {index} flush 실패: {e}"))?;
            Ok::<(), String>(())
        }
        .await;

        match transfer {
            Ok(()) if completed == segment_len => return Ok(()),
            Ok(()) if attempt + 1 < MAX_RETRIES => {
                tokio::time::sleep(Duration::from_millis(500 * (attempt as u64 + 1))).await;
            }
            Ok(()) => {
                return Err(format!(
                    "구간 {index} 크기 불일치: {completed}/{segment_len} bytes"
                ))
            }
            // 취소는 재시도하지 않고 즉시 올린다.
            Err(e) if e == CANCEL_SENTINEL => return Err(e),
            Err(e) if attempt + 1 < MAX_RETRIES => {
                tokio::time::sleep(Duration::from_millis(500 * (attempt as u64 + 1))).await;
                eprintln!("[segmented-download] 구간 {index} 재시도: {e}");
            }
            Err(e) => return Err(e),
        }
    }
    Err(format!("구간 {index} 재시도 횟수 초과"))
}

async fn segmented<F>(
    client: Client,
    request_info: DownloadRequest,
    total: u64,
    cancel: Arc<AtomicBool>,
    callback: Arc<F>,
) -> Result<PathBuf, String>
where
    F: Fn(DownloadProgress) + Send + Sync + 'static,
{
    let segment_count = (CONNECTIONS * SEGMENTS_PER_CONNECTION)
        .min(usize::try_from(total.max(1)).unwrap_or(usize::MAX))
        .max(1);
    let (part_path, meta_path, state_path, offsets) =
        prepare_resume(&request_info.destination, total, segment_count).await?;
    let resumed = offsets.iter().copied().sum::<u64>().min(total);
    let received = Arc::new(AtomicU64::new(resumed));
    let callback: Arc<dyn Fn(DownloadProgress) + Send + Sync> = callback;
    let progress = Arc::new(ProgressEmitter::new(
        received,
        Some(total),
        DownloadMode::Segmented,
        callback,
    ));
    progress.emit();

    let state_file = Arc::new(Mutex::new(
        tokio::fs::OpenOptions::new()
            .read(true)
            .write(true)
            .open(&state_path)
            .await
            .map_err(|e| format!("구간 상태 열기 실패: {e}"))?,
    ));
    let next = Arc::new(AtomicUsize::new(0));
    let offsets = Arc::new(offsets);
    let mut workers = JoinSet::new();

    for _ in 0..CONNECTIONS.min(segment_count) {
        let client = client.clone();
        let request_info = request_info.clone();
        let part_path = part_path.clone();
        let state_file = state_file.clone();
        let progress = progress.clone();
        let next = next.clone();
        let offsets = offsets.clone();
        let cancel = cancel.clone();
        workers.spawn(async move {
            loop {
                if cancelled(&cancel) {
                    return Err::<(), String>(CANCEL_SENTINEL.to_string());
                }
                let index = next.fetch_add(1, Ordering::Relaxed);
                if index >= segment_count {
                    return Ok::<(), String>(());
                }
                download_segment(
                    &client,
                    &request_info,
                    &part_path,
                    state_file.clone(),
                    progress.clone(),
                    cancel.clone(),
                    segment_count,
                    index,
                    offsets[index],
                )
                .await?;
            }
        });
    }

    while let Some(result) = workers.join_next().await {
        let joined = result.map_err(|e| format!("다운로드 작업 실행 실패: {e}"))?;
        if let Err(e) = joined {
            // 취소 sentinel은 감싸지 않고 그대로 올려 `download`가 Ok(None)으로 바꾸게 한다.
            if e == CANCEL_SENTINEL {
                return Err(CANCEL_SENTINEL.to_string());
            }
            return Err(format!("분할 다운로드 실패: {e}"));
        }
    }

    progress.received.store(total, Ordering::Relaxed);
    progress.emit();
    tokio::fs::rename(&part_path, &request_info.destination)
        .await
        .map_err(|e| {
            format!(
                "완료 파일 이동 실패({}): {e}",
                request_info.destination.display()
            )
        })?;
    let _ = tokio::fs::remove_file(meta_path).await;
    let _ = tokio::fs::remove_file(state_path).await;
    Ok(request_info.destination)
}

async fn single<F>(
    client: Client,
    request_info: DownloadRequest,
    expected_total: Option<u64>,
    cancel: Arc<AtomicBool>,
    callback: Arc<F>,
) -> Result<PathBuf, String>
where
    F: Fn(DownloadProgress) + Send + Sync + 'static,
{
    let part_path = sidecar_path(&request_info.destination, "download");
    let mut response = request(&client, reqwest::Method::GET, &request_info)
        .send()
        .await
        .map_err(|e| format!("단일 다운로드 연결 실패: {e}"))?;
    if !response.status().is_success() {
        return Err(format!("다운로드 서버 오류: HTTP {}", response.status()));
    }
    let total = response.content_length().or(expected_total);
    let received = Arc::new(AtomicU64::new(0));
    let callback: Arc<dyn Fn(DownloadProgress) + Send + Sync> = callback;
    let progress = ProgressEmitter::new(received, total, DownloadMode::Single, callback);
    progress.emit();

    let mut file = tokio::fs::File::create(&part_path)
        .await
        .map_err(|e| format!("임시 파일 생성 실패({}): {e}", part_path.display()))?;
    while let Some(chunk) = response
        .chunk()
        .await
        .map_err(|e| format!("다운로드 수신 실패: {e}"))?
    {
        if cancelled(&cancel) {
            return Err(CANCEL_SENTINEL.to_string());
        }
        file.write_all(&chunk)
            .await
            .map_err(|e| format!("파일 쓰기 실패: {e}"))?;
        progress
            .received
            .fetch_add(chunk.len() as u64, Ordering::Relaxed);
        progress.emit_if_due();
    }
    file.flush()
        .await
        .map_err(|e| format!("파일 flush 실패: {e}"))?;
    progress.emit();
    tokio::fs::rename(&part_path, &request_info.destination)
        .await
        .map_err(|e| {
            format!(
                "완료 파일 이동 실패({}): {e}",
                request_info.destination.display()
            )
        })?;
    Ok(request_info.destination)
}

/// 최종 URL을 받아 파일을 전송한다. `Ok(Some(path))` 성공, `Ok(None)` 취소, `Err` 실패.
/// 취소 시 sidecar를 남겨 다음 실행에서 재개할 수 있게 한다.
pub async fn download<F>(
    request_info: DownloadRequest,
    cancel: Arc<AtomicBool>,
    on_progress: F,
) -> Result<Option<PathBuf>, String>
where
    F: Fn(DownloadProgress) + Send + Sync + 'static,
{
    let client = client()?;
    let (range_supported, total) = probe_range(&client, &request_info).await?;
    let callback = Arc::new(on_progress);
    let result = match (range_supported, total) {
        (true, Some(total)) => segmented(client, request_info, total, cancel, callback).await,
        _ => single(client, request_info, total, cancel, callback).await,
    };
    match result {
        Ok(path) => Ok(Some(path)),
        Err(e) if e == CANCEL_SENTINEL => Ok(None),
        Err(e) => Err(e),
    }
}

