const CANCEL_SENTINEL: &str = "__DIST_DOWNLOAD_CANCELLED__";
const CONNECTIONS: usize = 8;
const SEGMENTS_PER_CONNECTION: usize = 2;
const MAX_RETRIES: usize = 4;
