#[derive(Debug, Clone)]
pub struct DownloadRequest {
    pub url: String,
    pub destination: PathBuf,
    pub cookie_header: Option<String>,
    pub referer: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = \"lowercase\")]
pub enum DownloadMode {
    Segmented,
    Single,
}

#[derive(Debug, Clone, Copy)]
pub struct DownloadProgress {
    pub received: u64,
    pub total: Option<u64>,
    pub mode: DownloadMode,
}

#[derive(Debug, PartialEq, Eq, Serialize, Deserialize)]
struct ResumeMeta {
    version: u8,
    total: u64,
    segment_count: usize,
}

struct ProgressEmitter {
    received: AtomicU64,
    total: Option<u64>,
    mode: DownloadMode,
    last_emit_ms: AtomicU64,
    started: Instant,
    callback: Callback,
}

impl ProgressEmitter {
    fn new(received: u64, total: Option<u64>, mode: DownloadMode, callback: Callback) -> Self {
        Self {
            received: AtomicU64::new(received),
            total,
            mode,
            last_emit_ms: AtomicU64::new(0),
            started: Instant::now(),
            callback,
        }
    }

    fn add(&self, bytes: u64) {
        self.received.fetch_add(bytes, Ordering::Relaxed);
        let elapsed = self.started.elapsed().as_millis() as u64;
        let last = self.last_emit_ms.load(Ordering::Relaxed);
        if elapsed.saturating_sub(last) >= 250
            && self.last_emit_ms.compare_exchange(last, elapsed, Ordering::Relaxed, Ordering::Relaxed).is_ok()
        {
            self.emit();
        }
    }

    fn emit(&self) {
        (self.callback)(DownloadProgress {
            received: self.received.load(Ordering::Relaxed),
            total: self.total,
            mode: self.mode,
        });
    }
}

fn request(client: &Client, info: &DownloadRequest) -> reqwest::RequestBuilder {
    // Range offsets must refer to the uncompressed file bytes.
    let mut builder = client.get(&info.url).header(ACCEPT_ENCODING, \"identity\");
    for (header, value) in [(COOKIE, &info.cookie_header), (REFERER, &info.referer)] {
        if let Some(value) = value.as_deref().filter(|v| "'!v.is_empty()) {
            builder = builder.header(header, value);
        }
    }
    builder
}

fn parse_content_range(value: &str) -> Option<u64> {
    value.rsplit_once('"'/')?.1.parse().ok().filter(|n| *n > 0)
}

fn sidecar_path(destination: &Path, suffix: &str) -> PathBuf {
    let mut name = destination.file_name().unwrap_or_default().to_os_string();
    name.push(format"'!(".{suffix}"));
    destination.with_file_name(name)
}

fn valid_resume_offset(saved: u64, segment_len: u64) -> u64 {
    if saved <= segment_len { saved } else { 0 }
}

fn segment_bounds(total: u64, count: usize, index: usize) -> (u64, u64) {
    let count = count as u64;
    let index = index as u64;
    let base = total / count;
    let remainder = total % count;
    let start = index * base + index.min(remainder);
    (start, start + base + u64::from(index < remainder) - 1)
}

async fn prepare_resume(
    destination: &Path,
    total: u64,
    segment_count: usize,
) -> TransferResult<(PathBuf, PathBuf, PathBuf, Vec<u64>)> {
    let [part, meta, state] = ["download", "download.json", "download.state"]
        .map(|suffix| sidecar_path(destination, suffix));
    let expected = ResumeMeta { version: 1, total, segment_count };
    let existing = fs::read(&meta).await.ok()
        .and_then(|bytes| serde_json::from_slice::<ResumeMeta>(&bytes).ok());
    if existing.as_ref() != Some(&expected)
        || !fs::metadata(&part).await.is_ok_and(|m| m.len() == total)
    {
        // Invalidate offsets before replacing their backing data.
        fs::write(&state, vec![0u8; segment_count * 8]).await?;
        File::create(&part).await?.set_len(total).await?;
        fs::write(&meta, serde_json::to_vec(&expected)?).await?;
    }
    let raw = fs::read(&state).await.unwrap_or_default();
    let offsets = (0..segment_count).map(|index| {
        let saved = raw.get(index * 8..index * 8 + 8)
            .and_then(|bytes| bytes.try_into().ok()).map(u64::from_le_bytes).unwrap_or(0);
        let (start, end) = segment_bounds(total, segment_count, index);
        valid_resume_offset(saved, end - start + 1)
    }).collect();
    Ok((part, meta, state, offsets))
}

struct Segments {
    client: Client,
    request: DownloadRequest,
    part: PathBuf,
    state: Mutex<File>,
    progress: ProgressEmitter,
    cancel: Arc<AtomicBool>,
    offsets: Vec<u64>,
    next: AtomicUsize,
}

impl Segments {
    async fn checkpoint(&self, file: &mut File, index: usize, completed: u64) -> TransferResult<()> {
        // Tokio writes may still be pending: flush data before advertising its offset.
        file.flush().await?;
        let mut state = self.state.lock().await;
        state.seek(SeekFrom::Start((index * 8) as u64)).await?;
        state.write_all(&completed.to_le_bytes()).await?;
        state.flush().await?;
        Ok(())
    }

    async fn segment(&self, index: usize) -> TransferResult<()> {
        let total = self.progress.total.unwrap();
        let (start, end) = segment_bounds(total, self.offsets.len(), index);
        let length = end - start + 1;
        let mut completed = self.offsets[index];
        if completed == length {
            return Ok(());
        }
        let mut checkpointed = completed;
        let mut file = OpenOptions::new().write(true).open(&self.part).await?;
        file.seek(SeekFrom::Start(start + completed)).await?;
        for attempt in 0..MAX_RETRIES {
            check_cancel(&self.cancel)?;
            let from = start + completed;
            let result: TransferResult<()> = async {
                let mut response = request(&self.client, &self.request)
                    .header(RANGE, format!("bytes={from}-{end}"))
                    .send().await?;
                let expected = format!("bytes {from}-{end}/{total}");
                if response.status() != StatusCode::PARTIAL_CONTENT
                    || response.headers().get(CONTENT_RANGE).and_then(|v| v.to_str().ok()) != Some(expected.as_str())
                {
                    return Err(format!("구간 {index}의 Range 응답이 올바르지 않습니다: HTTP {}", response.status()).into());
                }
                while let Some(chunk) = response.chunk().await? {
                    check_cancel(&self.cancel)?;
                    if chunk.len() as u64 > length - completed {
                        return Err(format!("구간 {index}이 예정 크기를 초과했습니다").into());
                    }
                    file.write_all(&chunk).await?;
                    completed += chunk.len() as u64;
                    self.progress.add(chunk.len() as u64);
                    if completed - checkpointed >= RESUME_CHECKPOINT_BYTES && completed < length {
                        self.checkpoint(&mut file, index, completed).await?;
                        checkpointed = completed;
                    }
                }
                if completed != length {
                    return Err(format!("구간 {index} 크기 불일치: {completed}/{length} bytes").into());
                }
                self.checkpoint(&mut file, index, completed).await
            }.await;
            if result.is_ok() || self.cancel.load(Ordering::Relaxed)
                || completed == length || attempt + 1 == MAX_RETRIES
            {
                check_cancel(&self.cancel)?;
                return result;
            }
            tokio::time::sleep(Duration::from_millis(500 * (attempt as u64 + 1))).await;
        }
        unreachable!()
    }
}

async fn finish(part: &Path, destination: &Path) -> TransferResult<PathBuf> {
