            total = body.content_length().or(total);
            response = Some(body);
            (
                sidecar_path(&request_info.destination, "download"),
                sidecar_path(&request_info.destination, "download.json"),
                sidecar_path(&request_info.destination, "download.state"),
                Vec::new(),
            )
        };
        let state = if range_total.is_some() {
            Some(tokio::sync::Mutex::new(
                OpenOptions::new()
                    .write(true)
                    .create(true)
                    .truncate(false)
                    .open(&state_path)
                    .await
                    .map_err(error)?,
            ))
        } else {
            None
        };
        let transfer = Arc::new(Transfer {
            client,
            info: request_info,
            part,
            cancel,
            state,
            progress: Progress {
                value: Mutex::new((
                    DownloadProgress {
                        received: offsets.iter().sum(),
                        total,
                        mode: if range_total.is_some() {
                            DownloadMode::Segmented
                        } else {
                            DownloadMode::Single
                        },
                    },
                    Instant::now(),
                )),
                callback: Box::new(on_progress),
            },
            offsets,
        });
        transfer.progress.emit(0, true);
        if let Some(total) = range_total {
            let mut next = 0;
            let mut workers = JoinSet::new();
            loop {
                while workers.len() < CONNECTIONS && next < transfer.offsets.len() {
                    let transfer = transfer.clone();
                    let index = next;
                    workers.spawn(async move { transfer.segment(total, index).await });
                    next += 1;
                }
                let Some(result) = workers.join_next().await else {
                    break;
                };
                if let Err(e) = result.map_err(error).and_then(|r| r) {
                    workers.abort_all();
                    while workers.join_next().await.is_some() {}
                    return Err(e);
                }
            }
        } else {
            transfer.single(response.unwrap()).await?;
        }
        transfer.progress.emit(0, true);
        transfer.check_cancel()?;
        let destination = transfer.info.destination.clone();
        let part = transfer.part.clone();
        drop(transfer);
        fs::rename(part, &destination).await.map_err(error)?;
        let _ = fs::remove_file(meta).await;
        let _ = fs::remove_file(state_path).await;
        Ok(destination)
    }
    .await;
    match result {
        Ok(path) => Ok(Some(path)),
        Err(e) if e == CANCEL_SENTINEL => Ok(None),
        Err(e) => Err(e),
    }
}

