fn boundaries_fallback_headers_and_progress() {
    let rt = rt();
    for (n, range) in [(0, RangeMode::Full), (1, RangeMode::Full), (2, RangeMode::Full),
        (15, RangeMode::Full), (17, RangeMode::Full), (65537, RangeMode::Full),
        (131071, RangeMode::Ignore), (131071, RangeMode::UnknownTotal)] {
        let data = body(n);
        let server = server::start(data.clone(), Behavior { range, redirect: true, ..Default::default() });
        let root = dir();
        let destination = root.join("file.bin");
        let events = Arc::new(Mutex::new(Vec::<DownloadProgress>::new()));
        let sink = events.clone();
        assert_eq!(rt.block_on(dl::download(info(server.redirect_url.clone(), destination.clone()), flag(),
            move |p| sink.lock().unwrap().push(p))).unwrap(), Some(destination.clone()));
        assert_eq!(&std::fs::read(&destination).unwrap(), data.as_ref());
        let events = events.lock().unwrap();
        assert!(events.len() >= 2);
        assert_eq!(events.last().unwrap().received, n as u64);
        assert_eq!(events.last().unwrap().mode, if range == RangeMode::Full && n > 0 { DownloadMode::Segmented } else { DownloadMode::Single });
        assert!(events.windows(2).all(|w| w[0].received <= w[1].received));
        for request in server.requests() {
            assert_eq!(request.header("accept-encoding"), Some("identity"));
            assert_eq!(request.header("cookie"), Some("session=secret"));
            assert_eq!(request.header("referer"), Some("https://example.test/download"));
        }
        assert!(server.max_active.load(Ordering::Relaxed) <= 8);
        std::fs::remove_dir_all(root).unwrap();
